import math
import itertools
from dispatchiq.helpers import route, route_cost, travel_min, drop_until_feasible

INF = 1e6
BIG = 1e9
INFEAS = 1e8
UNSCHED = 150.0
MOVE_PEN = 20.0
EPS = 1e-9


# --------------------------------------------------------------------------
# cost helpers: full route cost INCLUDING emergency_wait
# --------------------------------------------------------------------------
def _mp(state, jid, tid, tbyid):
    """Churn penalty (20) for moving a job off its healthy morning tech."""
    j = state["jobs"].get(jid)
    if j is None:
        return 0.0
    mt = j.get("morning_tech")
    if mt is None:
        return 0.0
    mtt = tbyid.get(mt)
    if mtt is None or mtt.get("sick"):
        return 0.0
    if mt == tid:
        return 0.0
    return MOVE_PEN


def _tc(state, tech, seq):
    """Feasible route cost for a tech, INCLUDING emergency_wait.
    Returns BIG if the route is infeasible."""
    if not seq:
        return 0.0
    jobs = state["jobs"]
    has_emerg = False
    for jid in seq:
        j = jobs.get(jid)
        if j is not None and j.get("emergency"):
            has_emerg = True
            break
    if not has_emerg:
        c = route_cost(state, tech, list(seq))
        return c if c < INF else BIG
    r = route(state, tech, list(seq))
    if not r.get("feasible", False):
        return BIG
    return (r.get("travel", 0.0) + r.get("weighted_late", 0.0) +
            r.get("overtime", 0.0) + r.get("emergency_wait", 0.0))


def _plan_cost(state, plan, tbyid):
    total = 0.0
    sched = set()
    jobs = state["jobs"]
    for tid, seq in plan.items():
        t = tbyid.get(tid)
        if t is None or t.get("sick"):
            if seq:
                return INFEAS
            continue
        if not seq:
            continue
        c = _tc(state, t, list(seq))
        if c >= BIG:
            return INFEAS
        total += c
        for jid in seq:
            if jid in sched:
                return INFEAS
            sched.add(jid)
            total += _mp(state, jid, tid, tbyid)
    for jid, j in jobs.items():
        if jid not in sched:
            total += UNSCHED * j["priority"]
    return total


def _recompute(state, plan, tbyid):
    costs = {}
    assigned = {}
    for tid, seq in plan.items():
        t = tbyid.get(tid)
        if t is None:
            continue
        costs[tid] = _tc(state, t, seq)
        if t.get("sick"):
            continue
        for jid in seq:
            assigned[jid] = tid
    return costs, assigned


# --------------------------------------------------------------------------
# seeds
# --------------------------------------------------------------------------
def _seed_morning(state, healthy, tbyid):
    plan = {t["id"]: [] for t in state["techs"]}
    for t in healthy:
        tid = t["id"]
        raw = list(t.get("remaining") or [])
        seen = set()
        seq = []
        for j in raw:
            if j in seen or j not in state["jobs"]:
                continue
            seen.add(j)
            seq.append(j)
        if seq and _tc(state, t, seq) >= BIG:
            seq, _ = drop_until_feasible(state, t, seq)
        plan[tid] = seq
    return plan


def _cluster_seed(state, healthy, tbyid):
    """Nearest-tech geographic assignment."""
    jobs = state["jobs"]
    plan = {t["id"]: [] for t in state["techs"]}
    by_skill = {}
    for jid, j in jobs.items():
        by_skill.setdefault(j["skill"], []).append(jid)

    for skill, jids in by_skill.items():
        techs = sorted([t for t in healthy if skill in t["skills"]],
                       key=lambda t: str(t["id"]))
        if not techs:
            continue
        pos = {t["id"]: (float(t["loc"][0]), float(t["loc"][1])) for t in techs}
        load = {t["id"]: float(t.get("free_at", 0)) for t in techs}
        order = sorted(jids, key=lambda j: (jobs[j]["earliest"],
                                            -jobs[j]["priority"], str(j)))
        for jid in order:
            jl = jobs[jid]["loc"]
            dur = float(jobs[jid]["duration"])
            best_tid = None
            best_score = None
            for t in techs:
                tid = t["id"]
                d = math.hypot(pos[tid][0] - jl[0], pos[tid][1] - jl[1])
                slack = (t["shift_end"] + t.get("max_overtime", 0)) - load[tid]
                score = d - 0.05 * slack
                if (best_score is None or score < best_score - 1e-12
                        or (abs(score - best_score) <= 1e-12
                            and (best_tid is None or str(tid) < str(best_tid)))):
                    best_score = score
                    best_tid = tid
            plan[best_tid].append(jid)
            d = math.hypot(pos[best_tid][0] - jl[0], pos[best_tid][1] - jl[1])
            pos[best_tid] = (float(jl[0]), float(jl[1]))
            load[best_tid] += dur + d * state["min_per_km"]

    for tid in list(plan.keys()):
        seq = plan[tid]
        if not seq:
            continue
        t = tbyid.get(tid)
        if t is None or t.get("sick"):
            plan[tid] = []
            continue
        seq.sort(key=lambda j: (jobs[j]["earliest"],
                                -jobs[j]["priority"], str(j)))
        if _tc(state, t, seq) >= BIG:
            seq, _ = drop_until_feasible(state, t, seq)
        plan[tid] = seq
    return plan


def _angular_cluster_seed(state, healthy, tbyid):
    """Geographic wedge clustering + best wedge->tech bijection."""
    jobs = state["jobs"]
    plan = {t["id"]: [] for t in state["techs"]}
    by_skill = {}
    for jid, j in jobs.items():
        by_skill.setdefault(j["skill"], []).append(jid)

    for skill, jids in by_skill.items():
        techs = sorted([t for t in healthy if skill in t["skills"]],
                       key=lambda t: str(t["id"]))
        if not techs:
            continue
        if len(techs) == 1:
            t = techs[0]
            seq = sorted(jids, key=lambda j: (jobs[j]["earliest"],
                                              -jobs[j]["priority"], str(j)))
            if seq and _tc(state, t, seq) >= BIG:
                seq, _ = drop_until_feasible(state, t, seq)
            plan[t["id"]] = seq
            continue

        cx = sum(jobs[j]["loc"][0] for j in jids) / float(len(jids))
        cy = sum(jobs[j]["loc"][1] for j in jids) / float(len(jids))
        ordered = sorted(jids, key=lambda j: (
            math.atan2(jobs[j]["loc"][1] - cy, jobs[j]["loc"][0] - cx),
            str(j)))
        n = len(techs)
        groups = [[] for _ in range(n)]
        L = len(ordered)
        for idx, jid in enumerate(ordered):
            g = min(idx * n // L, n - 1) if L > 0 else 0
            groups[g].append(jid)
        for g in groups:
            g.sort(key=lambda j: (jobs[j]["earliest"],
                                  -jobs[j]["priority"], str(j)))

        best_perm = None
        best_total = None
        perms = [tuple(range(n))]
        if n <= 5:
            perms = list(itertools.permutations(range(n)))
        for perm in perms:
            total = 0.0
            ok = True
            for gi, ti in enumerate(perm):
                t = techs[ti]
                seq = groups[gi]
                if not seq:
                    continue
                c = _tc(state, t, seq)
                if c >= BIG:
                    kept, _ = drop_until_feasible(state, t, seq)
                    if not kept:
                        c = 0.0
                    else:
                        c = _tc(state, t, kept)
                        if c >= BIG:
                            ok = False
                            break
                total += c
            if ok and (best_total is None or total < best_total - 1e-9):
                best_total = total
                best_perm = perm
        if best_perm is None:
            best_perm = tuple(range(n))

        for gi, ti in enumerate(best_perm):
            t = techs[ti]
            seq = groups[gi]
            if seq and _tc(state, t, seq) >= BIG:
                seq, _ = drop_until_feasible(state, t, seq)
            plan[t["id"]] = seq
    return plan


def _greedy_seed(state, healthy, tbyid):
    """Priority-descending best-insertion construction."""
    jobs = state["jobs"]
    plan = {t["id"]: [] for t in state["techs"]}
    costs = {t["id"]: 0.0 for t in state["techs"]}
    order = sorted(jobs.keys(), key=lambda j: (-jobs[j]["priority"],
                                               jobs[j]["earliest"],
                                               jobs[j]["release"],
                                               str(j)))
    for jid in order:
        job = jobs[jid]
        best = None
        for t in healthy:
            if job["skill"] not in t["skills"]:
                continue
            tid = t["id"]
            cand = _best_for_tech(state, t, plan[tid], costs[tid], jid, tbyid)
            if cand is None:
                continue
            d = cand[0]
            if best is None or d < best[0] - 1e-9 or (
                    abs(d - best[0]) <= 1e-9 and str(tid) < str(best[1])):
                best = (d, tid, cand)
        if best is not None:
            _d, tid, cand = best
            _delta, new_seq, new_cost, _dropped = cand
            plan[tid] = list(new_seq)
            costs[tid] = new_cost
    return plan


# --------------------------------------------------------------------------
# insertion helpers
# --------------------------------------------------------------------------
def _best_for_tech(state, tech, seq, old_cost, jid, tbyid):
    """Cheapest feasible insertion of `jid` into tech's seq."""
    tid = tech["id"]
    mp = _mp(state, jid, tid, tbyid)
    best = None
    for pos in range(len(seq) + 1):
        new_seq = list(seq[:pos]) + [jid] + list(seq[pos:])
        c = _tc(state, tech, new_seq)
        if c < BIG:
            d = c - old_cost + mp
            if best is None or d < best[0]:
                best = (d, new_seq, c, ())
        else:
            kept, dropped = drop_until_feasible(state, tech, new_seq)
            if jid not in kept:
                continue
            if any(state["jobs"][x]["emergency"] for x in dropped):
                continue
            c2 = _tc(state, tech, kept)
            if c2 >= BIG:
                continue
            d = c2 - old_cost + mp
            for x in dropped:
                d += UNSCHED * state["jobs"][x]["priority"] - _mp(state, x, tid, tbyid)
            if best is None or d < best[0]:
                best = (d, list(kept), c2, tuple(dropped))
    return best


def _regret_insert(state, healthy, plan, costs, assigned, pool, cache, tbyid,
                   only_emergency):
    """Regret-k insertion (k=2)."""
    n_ins = 0
    max_iters = 6 * len(state["jobs"]) + 40
    iters = 0
    while pool:
        iters += 1
        if iters > max_iters:
            break
        best_sel = None
        for jid in sorted(pool, key=lambda j: str(j)):
            job = state["jobs"][jid]
            if only_emergency and not job["emergency"]:
                continue
            opt = []
            for t in healthy:
                if job["skill"] not in t["skills"]:
                    continue
                tid = t["id"]
                key = (jid, tid)
                cand = cache.get(key)
                if cand is None:
                    cand = _best_for_tech(state, t, plan.get(tid, []),
                                          costs.get(tid, 0.0), jid, tbyid)
                    cache[key] = cand
                if cand is not None:
                    opt.append((cand[0], str(tid), tid, cand))
            if not opt:
                continue
            opt.sort(key=lambda x: (x[0], x[1]))
            d1 = opt[0][0]
            d2 = opt[1][0] if len(opt) > 1 else d1 + BIG
            regret = d2 - d1
            if not job["emergency"] and d1 >= UNSCHED * job["priority"] - 1e-9:
                continue
            sel = (-regret, -job["priority"], str(jid))
            if best_sel is None or sel < best_sel[0]:
                best_sel = (sel, jid, opt[0][2], opt[0][3])
        if best_sel is None:
            break
        _sel, jid, tid, cand = best_sel
        _delta, new_seq, new_cost, dropped = cand
        plan[tid] = list(new_seq)
        costs[tid] = new_cost
        assigned[jid] = tid
        pool.discard(jid)
        for x in dropped:
            assigned.pop(x, None)
            pool.add(x)
        for k in [k for k in cache if k[1] == tid]:
            del cache[k]
        n_ins += 1
    return n_ins


# --------------------------------------------------------------------------
# intra-route rebuild (better sequencing than a plain sort)
# --------------------------------------------------------------------------
def _rebuild_order(state, tech, seq):
    jobs = state["jobs"]
    if len(seq) <= 1:
        return list(seq), _tc(state, tech, seq)
    best_c = _tc(state, tech, seq)
    best_seq = list(seq)
    orders = [
        sorted(seq, key=lambda j: (jobs[j]["earliest"], -jobs[j]["priority"], str(j))),
        sorted(seq, key=lambda j: (-jobs[j]["priority"], jobs[j]["earliest"], str(j))),
        sorted(seq, key=lambda j: (jobs[j]["release"], jobs[j]["earliest"], str(j))),
        sorted(seq, key=lambda j: (0 if jobs[j]["emergency"] else 1,
                                   jobs[j]["release"], jobs[j]["earliest"], str(j))),
    ]
    for order in orders:
        cur = []
        for jid in order:
            best_val = None
            best_pos = None
            for p in range(len(cur) + 1):
                cand = cur[:p] + [jid] + cur[p:]
                c = _tc(state, tech, cand)
                if c >= BIG:
                    continue
                if best_val is None or c < best_val:
                    best_val = c
                    best_pos = p
            if best_pos is None:
                cur = cur + [jid]
            else:
                cur = cur[:best_pos] + [jid] + cur[best_pos:]
        c = _tc(state, tech, cur)
        if c < best_c - EPS:
            best_c = c
            best_seq = cur
    return best_seq, best_c


# --------------------------------------------------------------------------
# local search: Or-opt + 2-opt + relocate/drop + swap + rebuild
# --------------------------------------------------------------------------
def _local_search(state, healthy, plan, costs, assigned, tbyid, max_passes=2):
    jobs = state["jobs"]
    for _pass in range(max_passes):
        improved = False

        # (1) intra-route: Or-opt (segments 1-3) + 2-opt reversal
        for t in healthy:
            tid = t["id"]
            seq = list(plan.get(tid, []))
            n = len(seq)
            if n < 2:
                continue
            best_seq = seq
            best_cost = costs.get(tid, _tc(state, t, seq))
            for seg_len in (1, 2, 3):
                for i in range(n - seg_len + 1):
                    seg = seq[i:i + seg_len]
                    rest = seq[:i] + seq[i + seg_len:]
                    for pos in range(len(rest) + 1):
                        new_seq = rest[:pos] + seg + rest[pos:]
                        if new_seq == seq:
                            continue
                        c = _tc(state, t, new_seq)
                        if c < best_cost - EPS:
                            best_cost = c
                            best_seq = new_seq
            if n >= 3:
                for i in range(n - 1):
                    for j in range(i + 1, n):
                        new_seq = seq[:i] + seq[i:j + 1][::-1] + seq[j + 1:]
                        c = _tc(state, t, new_seq)
                        if c < best_cost - EPS:
                            best_cost = c
                            best_seq = new_seq
            if best_seq != seq:
                plan[tid] = best_seq
                costs[tid] = best_cost
                improved = True

        # (2) relocate / drop
        for jid in sorted(list(assigned.keys()), key=lambda j: str(j)):
            if jid not in assigned:
                continue
            cur_tid = assigned[jid]
            cur_tech = tbyid.get(cur_tid)
            cur_seq = list(plan.get(cur_tid, []))
            if cur_tech is None or jid not in cur_seq:
                continue
            job = jobs[jid]
            old_cur = costs.get(cur_tid, _tc(state, cur_tech, cur_seq))
            idx = cur_seq.index(jid)
            rm_seq = cur_seq[:idx] + cur_seq[idx + 1:]
            rm_cost = _tc(state, cur_tech, rm_seq)
            removal = rm_cost - old_cur - _mp(state, jid, cur_tid, tbyid)

            best_delta = 0.0
            best_action = None
            best_payload = None

            if not job["emergency"]:
                d = removal + UNSCHED * job["priority"]
                if d < -EPS:
                    best_delta = d
                    best_action = "drop"
                    best_payload = (rm_seq, rm_cost, None, None, None, ())

            for t in healthy:
                tid = t["id"]
                if tid == cur_tid:
                    continue
                if job["skill"] not in t["skills"]:
                    continue
                seq = list(plan.get(tid, []))
                old = costs.get(tid, _tc(state, t, seq))
                for pos in range(len(seq) + 1):
                    new_seq = seq[:pos] + [jid] + seq[pos:]
                    c = _tc(state, t, new_seq)
                    if c < BIG:
                        d = removal + (c - old) + _mp(state, jid, tid, tbyid)
                        if d < best_delta - EPS:
                            best_delta = d
                            best_action = "move"
                            best_payload = (rm_seq, rm_cost, tid, new_seq, c, ())
                    else:
                        kept, dropped = drop_until_feasible(state, t, new_seq)
                        if jid not in kept:
                            continue
                        if any(jobs[x]["emergency"] for x in dropped):
                            continue
                        c2 = _tc(state, t, kept)
                        if c2 >= BIG:
                            continue
                        d = removal + (c2 - old) + _mp(state, jid, tid, tbyid)
                        for x in dropped:
                            d += UNSCHED * jobs[x]["priority"] - _mp(state, x, tid, tbyid)
                        if d < best_delta - EPS:
                            best_delta = d
                            best_action = "move"
                            best_payload = (rm_seq, rm_cost, tid, list(kept), c2, tuple(dropped))

            if best_action is not None:
                plan[cur_tid] = list(best_payload[0])
                costs[cur_tid] = best_payload[1]
                assigned.pop(jid, None)
                if best_action == "move":
                    tid = best_payload[2]
                    plan[tid] = list(best_payload[3])
                    costs[tid] = best_payload[4]
                    assigned[jid] = tid
                    for x in best_payload[5]:
                        assigned.pop(x, None)
                improved = True

        # (3) swap jobs between techs
        for i in range(len(healthy)):
            t1 = healthy[i]
            tid1 = t1["id"]
            seq1 = list(plan.get(tid1, []))
            if not seq1:
                continue
            for j in range(i + 1, len(healthy)):
                t2 = healthy[j]
                tid2 = t2["id"]
                seq2 = list(plan.get(tid2, []))
                if not seq2:
                    continue
                cur_total = costs.get(tid1, 0.0) + costs.get(tid2, 0.0)
                best_total = cur_total
                best_s1 = seq1
                best_s2 = seq2
                for a in range(len(seq1)):
                    jid_a = seq1[a]
                    if jobs[jid_a]["skill"] not in t2["skills"]:
                        continue
                    for b in range(len(seq2)):
                        jid_b = seq2[b]
                        if jobs[jid_b]["skill"] not in t1["skills"]:
                            continue
                        ns1 = seq1[:a] + [jid_b] + seq1[a + 1:]
                        ns2 = seq2[:b] + [jid_a] + seq2[b + 1:]
                        c1 = _tc(state, t1, ns1)
                        if c1 >= BIG:
                            continue
                        c2 = _tc(state, t2, ns2)
                        if c2 >= BIG:
                            continue
                        churn = (_mp(state, jid_b, tid1, tbyid)
                                 + _mp(state, jid_a, tid2, tbyid)
                                 - _mp(state, jid_a, tid1, tbyid)
                                 - _mp(state, jid_b, tid2, tbyid))
                        if c1 + c2 + churn < best_total - EPS:
                            best_total = c1 + c2 + churn
                            best_s1 = ns1
                            best_s2 = ns2
                if best_s1 != seq1 or best_s2 != seq2:
                    plan[tid1] = best_s1
                    plan[tid2] = best_s2
                    costs[tid1] = _tc(state, t1, best_s1)
                    costs[tid2] = _tc(state, t2, best_s2)
                    for x in best_s1:
                        assigned[x] = tid1
                    for x in best_s2:
                        assigned[x] = tid2
                    improved = True
                    seq1 = best_s1
                    seq2 = best_s2

        # (4) re-insert unscheduled jobs (regret)
        pool = set(state["jobs"].keys()) - set(assigned.keys())
        if pool:
            cache = {}
            inserted = _regret_insert(state, healthy, plan, costs, assigned,
                                      pool, cache, tbyid, False)
            if inserted:
                improved = True

        # (5) route rebuild (better sequencing)
        for t in healthy:
            tid = t["id"]
            seq = list(plan.get(tid, []))
            if len(seq) < 2:
                continue
            ns, nc = _rebuild_order(state, t, seq)
            if nc < costs.get(tid, BIG) - EPS:
                plan[tid] = ns
                costs[tid] = nc
                improved = True

        if not improved:
            break


# --------------------------------------------------------------------------
# greedy reinsertion delta for ejection chains
# --------------------------------------------------------------------------
def _greedy_reinsert_delta(state, victims, plan, costs, tbyid, base_override=None):
    """Return the total cost adjustment if we reinsert the victims
    (greedily one after another) instead of leaving them unscheduled.
    Positive values mean reinsertion is more expensive than dropping."""
    local_plan = {tid: list(seq) for tid, seq in plan.items()}
    if base_override:
        for tid, seq in base_override.items():
            local_plan[tid] = list(seq)
    local_costs = {}
    for tid, seq in local_plan.items():
        t = tbyid.get(tid)
        if t:
            local_costs[tid] = _tc(state, t, seq)
    total_adj = 0.0
    for jid in victims:
        job = state["jobs"].get(jid)
        if job is None:
            continue
        best = None
        for t in state["techs"]:
            if t.get("sick"):
                continue
            if job["skill"] not in t["skills"]:
                continue
            tid = t["id"]
            seq = local_plan.get(tid, [])
            old = local_costs.get(tid, _tc(state, t, seq))
            for pos in range(len(seq) + 1):
                cand = seq[:pos] + [jid] + seq[pos:]
                c = _tc(state, t, cand)
                if c >= BIG:
                    continue
                delta = (c - old) + _mp(state, jid, tid, tbyid)
                if best is None or delta < best[0]:
                    best = (delta, tid, cand, c)
        if best is not None:
            delta, tid, cand, c = best
            total_adj += delta - UNSCHED * job["priority"]
            local_plan[tid] = cand
            local_costs[tid] = c
        # else: cannot reinsert, keep the unscheduled penalty already in d
    return total_adj


# --------------------------------------------------------------------------
# eviction / bump pass with lookahead reinsertion (no gating)
# --------------------------------------------------------------------------
def _evict_pass(state, healthy, plan, costs, assigned, tbyid,
                max_rounds=2, budget=3000, allow_two=True):
    jobs = state["jobs"]
    used = 0
    improved = False
    for _round in range(max_rounds):
        changed = False
        unsched = sorted([j for j in jobs if j not in assigned],
                         key=lambda j: (-jobs[j]["priority"],
                                        jobs[j]["earliest"],
                                        jobs[j]["release"],
                                        str(j)))
        if not unsched:
            break
        for u in unsched:
            if u in assigned:
                continue
            if used >= budget:
                break
            ju = jobs[u]
            best = None  # (adj_d, d, tid, nseq, c2, victims)
            for t in healthy:
                if ju["skill"] not in t["skills"]:
                    continue
                tid = t["id"]
                seq = list(plan.get(tid, []))
                old = costs.get(tid, _tc(state, t, seq))
                mpu = _mp(state, u, tid, tbyid)
                base_val = mpu - UNSCHED * ju["priority"]
                for p in range(len(seq) + 1):
                    cand = seq[:p] + [u] + seq[p:]
                    used += 1
                    c0 = _tc(state, t, cand)
                    if c0 < BIG:
                        d = (c0 - old) + base_val
                        if d < -EPS:
                            if best is None or d < best[0] - EPS:
                                best = (d, d, tid, cand, c0, ())
                        if used >= budget:
                            break
                        continue
                    ncand = len(cand)
                    # single eviction
                    for i in range(ncand):
                        v = cand[i]
                        if v == u:
                            continue
                        vj = jobs.get(v)
                        if vj is None or vj["emergency"]:
                            continue
                        nseq = cand[:i] + cand[i + 1:]
                        c2 = _tc(state, t, nseq)
                        used += 1
                        if c2 >= BIG:
                            continue
                        d = (c2 - old) + base_val
                        d += UNSCHED * vj["priority"] - _mp(state, v, tid, tbyid)
                        adj_d = d + _greedy_reinsert_delta(
                            state, [v], plan, costs, tbyid,
                            base_override={tid: nseq})
                        if adj_d < -EPS and (best is None or adj_d < best[0] - EPS):
                            best = (adj_d, d, tid, nseq, c2, (v,))
                    # double eviction
                    if allow_two and ju["priority"] >= 3 and ncand >= 4:
                        for i in range(ncand):
                            v1 = cand[i]
                            if v1 == u:
                                continue
                            j1 = jobs.get(v1)
                            if j1 is None or j1["emergency"]:
                                continue
                            for k in range(i + 1, ncand):
                                v2 = cand[k]
                                if v2 == u:
                                    continue
                                j2 = jobs.get(v2)
                                if j2 is None or j2["emergency"]:
                                    continue
                                nseq = cand[:i] + cand[i + 1:k] + cand[k + 1:]
                                c3 = _tc(state, t, nseq)
                                used += 1
                                if c3 >= BIG:
                                    continue
                                d = (c3 - old) + base_val
                                d += UNSCHED * j1["priority"] - _mp(state, v1, tid, tbyid)
                                d += UNSCHED * j2["priority"] - _mp(state, v2, tid, tbyid)
                                adj_d = d + _greedy_reinsert_delta(
                                    state, [v1, v2], plan, costs, tbyid,
                                    base_override={tid: nseq})
                                if adj_d < -EPS and (best is None or adj_d < best[0] - EPS):
                                    best = (adj_d, d, tid, nseq, c3, (v1, v2))
                                if used >= budget:
                                    break
                            if used >= budget:
                                break
                    if used >= budget:
                        break
                if used >= budget:
                    break
            if best is None:
                continue
            _adj_d, _d, tid, nseq, c2, victims = best
            plan[tid] = list(nseq)
            costs[tid] = c2
            assigned[u] = tid
            for v in victims:
                assigned.pop(v, None)
            changed = True
            improved = True
            if victims:
                _regret_insert(state, healthy, plan, costs, assigned,
                               set(victims), {}, tbyid, False)
            if used >= budget:
                break
        if not changed or used >= budget:
            break
    return improved


# --------------------------------------------------------------------------
# safety net: guarantee every emergency is placed
# --------------------------------------------------------------------------
def _safety_net(state, healthy, plan, tbyid):
    jobs = state["jobs"]
    sched = set()
    for seq in plan.values():
        sched.update(seq)
    emerg = sorted([j for j, v in jobs.items() if v["emergency"]],
                   key=lambda j: (jobs[j]["release"], -jobs[j]["priority"], str(j)))
    for jid in emerg:
        if jid in sched:
            continue
        job = jobs[jid]
        best = None
        for t in healthy:
            if job["skill"] not in t["skills"]:
                continue
            tid = t["id"]
            base = list(plan.get(tid, []))
            for p in range(len(base) + 1):
                cand = base[:p] + [jid] + base[p:]
                kept, dropped = drop_until_feasible(state, t, cand)
                if jid not in kept:
                    continue
                if any(jobs[x]["emergency"] for x in dropped):
                    continue
                c = _tc(state, t, kept)
                if c >= BIG:
                    continue
                key = (len(dropped), len(kept), c, str(tid), p)
                if best is None or key < best[0]:
                    best = (key, tid, list(kept))
        if best is not None:
            _k, tid, kept = best
            plan[tid] = kept
        else:
            for t in healthy:
                if job["skill"] in t["skills"]:
                    tid = t["id"]
                    plan[tid] = list(plan.get(tid, [])) + [jid]
                    break
        sched = set()
        for seq in plan.values():
            sched.update(seq)
    return plan


# --------------------------------------------------------------------------
# load balancing: move jobs from overtime/late techs to slack techs
# --------------------------------------------------------------------------
def _balance_pass(state, healthy, plan, costs, assigned, tbyid,
                  max_rounds=2, budget=1200):
    jobs = state["jobs"]
    used = 0
    improved = False
    for _round in range(max_rounds):
        changed = False
        info = {}
        for t in healthy:
            tid = t["id"]
            seq = list(plan.get(tid, []))
            if not seq:
                info[tid] = {"overtime": 0.0, "weighted_late": 0.0,
                             "end": t.get("free_at", 0),
                             "emergency_wait": 0.0, "feasible": True}
            else:
                r = route(state, t, seq)
                info[tid] = r if r.get("feasible", False) else None
        sources = [t for t in healthy if info[t["id"]] is not None and
                   (info[t["id"]]["overtime"] > EPS or
                    info[t["id"]]["weighted_late"] > EPS)]
        sources.sort(key=lambda t: (-(info[t["id"]]["overtime"] +
                                      info[t["id"]]["weighted_late"]),
                                    str(t["id"])))
        for src in sources:
            if used >= budget or changed:
                break
            src_id = src["id"]
            src_seq = list(plan.get(src_id, []))
            if not src_seq:
                continue
            src_cost = costs.get(src_id, _tc(state, src, src_seq))
            job_indices = sorted(range(len(src_seq)),
                                 key=lambda i: (-jobs[src_seq[i]]["priority"], i))
            for idx in job_indices:
                if used >= budget or changed:
                    break
                jid = src_seq[idx]
                job = jobs.get(jid)
                if job is None:
                    continue
                new_src_seq = src_seq[:idx] + src_seq[idx + 1:]
                src_removed_cost = _tc(state, src, new_src_seq)
                if src_removed_cost >= BIG:
                    continue
                removal_delta = (src_removed_cost - src_cost -
                                 _mp(state, jid, src_id, tbyid))
                best = None
                for dst in healthy:
                    if used >= budget or changed:
                        break
                    if dst["id"] == src_id:
                        continue
                    if job["skill"] not in dst["skills"]:
                        continue
                    dst_info = info.get(dst["id"])
                    if dst_info is None:
                        continue
                    if dst_info["overtime"] > EPS:
                        continue
                    dst_seq = list(plan.get(dst["id"], []))
                    dst_cost = costs.get(dst["id"], _tc(state, dst, dst_seq))
                    for pos in range(len(dst_seq) + 1):
                        used += 1
                        cand_dst_seq = dst_seq[:pos] + [jid] + dst_seq[pos:]
                        c = _tc(state, dst, cand_dst_seq)
                        if c >= BIG:
                            continue
                        r_dst = route(state, dst, cand_dst_seq)
                        if r_dst.get("overtime", 0.0) > EPS:
                            continue
                        if not r_dst.get("feasible", False):
                            continue
                        delta = (removal_delta + (c - dst_cost) +
                                 _mp(state, jid, dst["id"], tbyid))
                        if delta < -EPS:
                            key = (delta, str(dst["id"]), pos)
                            if best is None or key < best[0]:
                                best = (key, dst["id"], cand_dst_seq, c)
                        if used >= budget:
                            break
                    if used >= budget:
                        break
                if best is not None:
                    _k, dst_id, new_dst_seq, new_dst_cost = best
                    plan[src_id] = list(new_src_seq)
                    costs[src_id] = src_removed_cost
                    plan[dst_id] = list(new_dst_seq)
                    costs[dst_id] = new_dst_cost
                    assigned.pop(jid, None)
                    assigned[jid] = dst_id
                    changed = True
                    improved = True
                    break
            if changed:
                break
        if not changed:
            break
    return improved


# --------------------------------------------------------------------------
# chain pass: move a job to a slack tech, then insert an unscheduled job
# on the freed source tech (partial coverage allowed).
# --------------------------------------------------------------------------
def _chain_pass(state, healthy, plan, costs, assigned, tbyid, budget=600):
    jobs = state["jobs"]
    used = 0
    improved = False
    for _round in range(2):
        changed = False
        info = {}
        for t in healthy:
            tid = t["id"]
            seq = list(plan.get(tid, []))
            if not seq:
                info[tid] = {"overtime": 0.0, "weighted_late": 0.0,
                             "end": t.get("free_at", 0),
                             "emergency_wait": 0.0, "feasible": True}
            else:
                r = route(state, t, seq)
                info[tid] = r if r.get("feasible", False) else None
        sources = [t for t in healthy if info[t["id"]] is not None and
                   (info[t["id"]]["overtime"] > EPS or
                    info[t["id"]]["weighted_late"] > EPS)]
        sources.sort(key=lambda t: (-(info[t["id"]]["overtime"] +
                                      info[t["id"]]["weighted_late"]),
                                    str(t["id"])))
        unsched = sorted([j for j in jobs if j not in assigned],
                         key=lambda j: (-jobs[j]["priority"],
                                        jobs[j]["earliest"], str(j)))
        if not unsched:
            break
        unsched = unsched[:6]
        for src in sources:
            if used >= budget or changed:
                break
            src_id = src["id"]
            src_seq = list(plan.get(src_id, []))
            if not src_seq:
                continue
            src_cost = costs.get(src_id, _tc(state, src, src_seq))
            job_indices = sorted(range(len(src_seq)),
                                 key=lambda i: (-jobs[src_seq[i]]["priority"], i))
            for idx in job_indices:
                if used >= budget or changed:
                    break
                jid = src_seq[idx]
                job = jobs.get(jid)
                if job is None:
                    continue
                new_src_seq = src_seq[:idx] + src_seq[idx + 1:]
                src_removed_cost = _tc(state, src, new_src_seq)
                if src_removed_cost >= BIG:
                    continue
                removal_delta = (src_removed_cost - src_cost -
                                 _mp(state, jid, src_id, tbyid))
                best_chain = None
                for dst in healthy:
                    if used >= budget or changed:
                        break
                    if dst["id"] == src_id:
                        continue
                    if job["skill"] not in dst["skills"]:
                        continue
                    dst_info = info.get(dst["id"])
                    if dst_info is None:
                        continue
                    if dst_info["overtime"] > EPS:
                        continue
                    dst_seq = list(plan.get(dst["id"], []))
                    dst_cost = costs.get(dst["id"], _tc(state, dst, dst_seq))
                    cand_dst = _best_for_tech(state, dst, dst_seq, dst_cost,
                                              jid, tbyid)
                    if cand_dst is None:
                        continue
                    d, new_dst_seq, new_dst_cost, dropped_dst = cand_dst
                    if dropped_dst:
                        continue
                    move_delta = removal_delta + d
                    # strict improvement first
                    if move_delta < -EPS:
                        key = (move_delta, str(dst["id"]), "", "")
                        if best_chain is None or key < best_chain[0]:
                            best_chain = (key, dst["id"], new_dst_seq,
                                          new_dst_cost, None, new_src_seq,
                                          src_removed_cost, ())
                    # chain with unscheduled insertion
                    if move_delta < 750.0:
                        for u in unsched:
                            if u == jid:
                                continue
                            uj = jobs[u]
                            if uj["skill"] not in src["skills"]:
                                continue
                            cand_u = _best_for_tech(state, src, new_src_seq,
                                                    src_removed_cost, u, tbyid)
                            if cand_u is None:
                                continue
                            du, new_src_seq_u, new_src_cost_u, dropped_u = cand_u
                            chain_delta = (move_delta + du -
                                           UNSCHED * uj["priority"])
                            if chain_delta < -EPS:
                                key = (chain_delta, str(dst["id"]), str(u), "")
                                if best_chain is None or key < best_chain[0]:
                                    best_chain = (key, dst["id"], new_dst_seq,
                                                  new_dst_cost, u,
                                                  new_src_seq_u, new_src_cost_u,
                                                  dropped_u)
                            used += 1
                            if used >= budget:
                                break
                if best_chain is not None:
                    (key, dst_id, new_dst_seq, new_dst_cost,
                     u, new_src_seq_u, new_src_cost_u, dropped_u) = best_chain
                    if u is None:
                        plan[src_id] = list(new_src_seq)
                        costs[src_id] = src_removed_cost
                    else:
                        plan[src_id] = list(new_src_seq_u)
                        costs[src_id] = new_src_cost_u
                        assigned[u] = src_id
                        for x in dropped_u:
                            assigned.pop(x, None)
                    plan[dst_id] = list(new_dst_seq)
                    costs[dst_id] = new_dst_cost
                    assigned.pop(jid, None)
                    assigned[jid] = dst_id
                    changed = True
                    improved = True
                    break
            if changed:
                break
        if not changed:
            break
    return improved


# --------------------------------------------------------------------------
# full pipeline for a single seed
# --------------------------------------------------------------------------
def _solve(state, healthy, tbyid, plan, max_passes=2, do_evict=True):
    costs, assigned = _recompute(state, plan, tbyid)
    pool = set(state["jobs"].keys()) - set(assigned.keys())

    cache = {}
    _regret_insert(state, healthy, plan, costs, assigned, pool, cache, tbyid, True)
    _regret_insert(state, healthy, plan, costs, assigned, pool, cache, tbyid, False)

    _local_search(state, healthy, plan, costs, assigned, tbyid, max_passes=max_passes)
    _safety_net(state, healthy, plan, tbyid)

    if do_evict:
        costs, assigned = _recompute(state, plan, tbyid)
        _evict_pass(state, healthy, plan, costs, assigned, tbyid)
        _safety_net(state, healthy, plan, tbyid)

        costs, assigned = _recompute(state, plan, tbyid)
        pool = set(state["jobs"].keys()) - set(assigned.keys())
        if pool:
            _regret_insert(state, healthy, plan, costs, assigned, pool, {}, tbyid, False)
        _local_search(state, healthy, plan, costs, assigned, tbyid, max_passes=1)

    _safety_net(state, healthy, plan, tbyid)
    return plan


# --------------------------------------------------------------------------
# entry point
# --------------------------------------------------------------------------
def replan(state):
    techs = list(state["techs"])
    tbyid = {t["id"]: t for t in techs}
    healthy = sorted([t for t in techs if not t.get("sick")],
                     key=lambda t: str(t["id"]))

    seeds = []
    for fn in (_seed_morning, _cluster_seed, _angular_cluster_seed, _greedy_seed):
        try:
            p = fn(state, healthy, tbyid)
        except Exception:
            p = None
        if p is None:
            continue
        for t in techs:
            p.setdefault(t["id"], [])
            if t.get("sick"):
                p[t["id"]] = []
        seeds.append(p)

    if not seeds:
        seeds.append({t["id"]: [] for t in techs})

    scored = []
    for idx, p in enumerate(seeds):
        try:
            _solve(state, healthy, tbyid, p, max_passes=1, do_evict=False)
        except Exception:
            pass
        try:
            c = _plan_cost(state, p, tbyid)
        except Exception:
            c = INFEAS
        if c >= INFEAS:
            c = INFEAS
        scored.append((c, idx, p))
    scored.sort(key=lambda x: (x[0], x[1]))

    best_plan = None
    best_cost = INFEAS
    for c, idx, p in scored[:2]:
        try:
            _solve(state, healthy, tbyid, p, max_passes=2, do_evict=True)
        except Exception:
            pass
        try:
            cc = _plan_cost(state, p, tbyid)
        except Exception:
            cc = INFEAS
        if cc < best_cost - EPS:
            best_cost = cc
            best_plan = p

    if best_plan is None:
        for c, idx, p in scored:
            if c < INFEAS:
                best_plan = p
                best_cost = c
                break

    if best_plan is None:
        best_plan = {t["id"]: [] for t in techs}
        try:
            _solve(state, healthy, tbyid, best_plan, max_passes=2, do_evict=True)
        except Exception:
            pass

    # final load-balancing / chain polish on the best plan
    try:
        costs, assigned = _recompute(state, best_plan, tbyid)
        _balance_pass(state, healthy, best_plan, costs, assigned, tbyid,
                      max_rounds=2, budget=1200)
        costs, assigned = _recompute(state, best_plan, tbyid)
        _chain_pass(state, healthy, best_plan, costs, assigned, tbyid, budget=600)
    except Exception:
        pass

    _safety_net(state, healthy, best_plan, tbyid)

    for t in techs:
        if t.get("sick"):
            best_plan[t["id"]] = []

    return {t["id"]: list(best_plan.get(t["id"], [])) for t in techs}
